"""Pydantic schemas for LLM task breakdown outputs."""

from pydantic import BaseModel, field_validator


class LLMTask(BaseModel):
    """Schema for a single study task generated by LLM."""

    title: str
    description: str | None = None
    estimated_minutes: int

    model_config = {"extra": "forbid"}

    @field_validator("title")
    @classmethod
    def check_title(cls, v: str) -> str:
        if not v or not v.strip():
            raise ValueError("task title cannot be empty")
        if len(v) > 120:
            raise ValueError("task title cannot exceed 120 characters")
        return v.strip()

    @field_validator("description")
    @classmethod
    def check_description(cls, v: str | None) -> str | None:
        if v is None:
            return None
        cleaned = v.strip()
        if not cleaned:
            return None
        if len(cleaned) > 500:
            raise ValueError("task description cannot exceed 500 characters")
        return cleaned

    @field_validator("estimated_minutes")
    @classmethod
    def check_estimated_minutes(cls, v: int) -> int:
        if v < 10:
            raise ValueError("estimated_minutes must be at least 10")
        if v > 480:
            raise ValueError("estimated_minutes cannot exceed 480")
        return v


class LLMTaskBreakdown(BaseModel):
    """Schema for complete task breakdown output from LLM."""

    tasks: list[LLMTask]

    model_config = {"extra": "forbid"}

    @field_validator("tasks")
    @classmethod
    def check_tasks_count(cls, v: list[LLMTask]) -> list[LLMTask]:
        if not v:
            raise ValueError("tasks list cannot be empty")
        if len(v) > 50:
            raise ValueError("tasks list cannot exceed 50 tasks")
        return v
